-- +goose Up
-- Phase 3 (3-4): Better Auth's tables, generated by the pinned CLI (better-auth 1.7.12, with the
-- email OTP, organization, device authorization and bearer plugins and Goal's additional fields of
-- auth/src/auth.ts) against a database migrated to 00040:
--   pnpm --filter @goal/auth exec auth generate --config src/generate.ts --output <file>
-- Changed by hand, as spec 3 §6.2 says: this header, every id default gen_random_uuid() (v4) set to
-- goal_uuidv7() (00040), the grants at the end, and the generated `create schema if not exists
-- "auth"` left out (00040 creates it). Never edited after it is applied; a change of Better Auth's
-- schema is a new migration, and task auth:schema-check fails until there is one. Columns are
-- Better Auth's camelCase, quoted; Goal reads them only inside definer functions.

create table "auth"."user" ("id" uuid default goal_uuidv7() not null primary key, "name" text not null, "email" text not null unique, "emailVerified" boolean not null, "image" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

create table "auth"."session" ("id" uuid default goal_uuidv7() not null primary key, "expiresAt" timestamptz not null, "token" text not null unique, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null, "ipAddress" text, "userAgent" text, "userId" uuid not null references "auth"."user" ("id") on delete cascade, "activeOrganizationId" text);

create table "auth"."account" ("id" uuid default goal_uuidv7() not null primary key, "accountId" text not null, "providerId" text not null, "userId" uuid not null references "auth"."user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null);

create table "auth"."verification" ("id" uuid default goal_uuidv7() not null primary key, "identifier" text not null, "value" text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

create table "auth"."organization" ("id" uuid default goal_uuidv7() not null primary key, "name" text not null, "slug" text not null unique, "logo" text, "createdAt" timestamptz not null, "metadata" text);

create table "auth"."member" ("id" uuid default goal_uuidv7() not null primary key, "organizationId" uuid not null references "auth"."organization" ("id") on delete cascade, "userId" uuid not null references "auth"."user" ("id") on delete cascade, "role" text not null, "createdAt" timestamptz not null, "changedBy" text, "changedAt" timestamptz);

create table "auth"."invitation" ("id" uuid default goal_uuidv7() not null primary key, "organizationId" uuid not null references "auth"."organization" ("id") on delete cascade, "email" text not null, "role" text, "status" text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "inviterId" uuid not null references "auth"."user" ("id") on delete cascade, "factoryRoles" text, "changedBy" text, "changedAt" timestamptz);

create table "auth"."deviceCode" ("id" uuid default goal_uuidv7() not null primary key, "deviceCode" text not null, "userCode" text not null, "userId" text, "expiresAt" timestamptz not null, "status" text not null, "lastPolledAt" timestamptz, "pollingInterval" integer, "clientId" text, "scope" text);

create table "auth"."rateLimit" ("id" uuid default goal_uuidv7() not null primary key, "key" text not null unique, "count" integer not null, "lastRequest" bigint not null);

create index "session_userId_idx" on "auth"."session" ("userId");

create index "account_userId_idx" on "auth"."account" ("userId");

create index "verification_identifier_idx" on "auth"."verification" ("identifier");

create index "member_organizationId_idx" on "auth"."member" ("organizationId");

create index "member_userId_idx" on "auth"."member" ("userId");

create index "invitation_organizationId_idx" on "auth"."invitation" ("organizationId");

create index "invitation_email_idx" on "auth"."invitation" ("email");

create unique index "deviceCode_deviceCode_uidx" on "auth"."deviceCode" ("deviceCode");

create unique index "deviceCode_userCode_uidx" on "auth"."deviceCode" ("userCode");

-- goal_auth (the identity service) reads and writes these rows and nothing else; goal_app gets
-- nothing here (no USAGE on schema auth).
GRANT SELECT, INSERT, UPDATE, DELETE ON
  auth."user",
  auth.session,
  auth.account,
  auth.verification,
  auth.organization,
  auth.member,
  auth.invitation,
  auth."deviceCode",
  auth."rateLimit"
TO goal_auth;
